package ntnu.bidata.iir.sensornode;

import java.util.concurrent.ThreadLocalRandom;

/**
 * Simulated sensor whose value drifts randomly inside [min, max].
 * Two things can move it on purpose: an actuator can push it (setDrift), and a sensor with a
 * "pull" settles back towards its start value, so it does not wander off on its own.
 */
// Code generated by an AI
public class RandomWalkSensor extends Sensor {
    private final double min;
    private final double max;
    private final double step;
    private final double baseline; // the start value; what the sensor settles towards
    private final double pull;     // fraction of the distance to the baseline recovered per reading
    private double value;
    private volatile double drift; // added on every read; set by actuators (heater, fire, extractor...)

    public RandomWalkSensor(String id, double start, double min, double max, double step, double pull) {
        super(id);
        this.value = start;
        this.baseline = start;
        this.min = min;
        this.max = max;
        this.step = step;
        this.pull = pull;
    }

    /** The latest value, without producing a new reading. */
    public synchronized double current() {
        return value;
    }

    /** Constant push per reading, e.g. +0.3 while a heater is on. */
    public void setDrift(double drift) {this.drift = drift;}

    @Override
    public synchronized double read() {
        value += ThreadLocalRandom.current().nextDouble(-step, step) + drift - pull * (value - baseline);
        value = Math.max(min, Math.min(max, value));
        return value;
    }
}
